//! Unrun owner question/reply/reuse fixtures. No Telegram send or browser action.
async fn owner_question_call(c:&mut PgConnection,path:&str,value:Value)->Result<Value>{let config=Configuration::from_values(&queue_runtime_values()).unwrap();let route=automated_apply_agents::execution::route(path).unwrap();automated_apply_agents::execution::dispatch_body_configured(c,route,route.method(),None,value.to_string().as_bytes(),Some(&config)).await}
async fn owner_question_packet()->(PgConnection,Value,Value){
    let(mut c,job)=packet_service_fixture().await;let packet=packet_create(&mut c,job,"fictional-owner-questions",json!([{"question":"Preferred shift?","options":["Day","Night"],"field_type":"multiple_choice","required":true},{"question":"Preferred contact method?","options":["Email","Phone"],"field_type":"multiple_choice","required":true}])).await.unwrap();
    let id=Uuid::new_v4();let intent=json!({"id":id,"job_id":job,"platform":packet["platform"],"packet_id":packet["id"],"normalized_url":packet["snapshot"]["destination"]["application_url"],"role":packet["snapshot"]["job_title"],"employer":packet["snapshot"]["company_name"],"profile_version":packet["candidate_profile_version"],"state":"NEEDS_INPUT","revision":1,"history":[],"cancelled":false,"fence":0,"attempts":0,"approved_answer_revisions":{}});browser_save(&mut c,&format!("exec:{id}"),intent.clone()).await;(c,packet,intent)
}
fn owner_question_ask_path(intent:&Value,field:&Value)->String{format!("/api/v1/execution/{}/questions/{}",intent["id"].as_str().unwrap(),field["id"].as_str().unwrap())}
fn owner_question_answer_path(question:&Value)->String{format!("/api/v1/execution/questions/{}/answer",question["id"].as_str().unwrap())}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_questions_share_envelope_identity_and_answer_updates_guarded_field_once(){
    let(mut c,packet,intent)=owner_question_packet().await;let field=&packet["fields"][7];let path=owner_question_ask_path(&intent,field);let q=owner_question_call(&mut c,&path,Value::Null).await.unwrap();assert_eq!(q,owner_question_call(&mut c,&path,Value::Null).await.unwrap());assert_eq!(q["reuse_approved"],false);assert!(q.get("extension_task_id").is_none());let packet_id=packet["id"].as_str().unwrap().parse().unwrap();assert!(!sqlx::query_scalar::<_,bool>("SELECT EXISTS(SELECT 1 FROM owner_preferences WHERE key=$1)").bind(automated_apply_agents::packet_archive::key(packet_id,1).unwrap()).fetch_one(&mut c).await.unwrap());
    let answered=owner_question_call(&mut c,&owner_question_answer_path(&q),json!({"expected_revision":1,"answer":" Day "})).await.unwrap();assert_eq!(answered["answer"],"Day");assert_eq!(answered["provenance"]["source"],"owner_dashboard");assert_eq!(answered["answer_revision"],field["answer_revision"].as_i64().unwrap()+1);assert_eq!(answered["reuse_approved"],false);let saved:Value=sqlx::query_scalar("SELECT to_jsonb(f) FROM application_packet_fields f WHERE id=$1").bind(field["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert_eq!(saved["answer_revision"],answered["answer_revision"]);assert_eq!(saved["provenance"]["telegram_question"],q["id"]);assert_eq!(saved["provenance"]["answer_expires_at"],answered["answer_expires_at"]);assert_eq!(saved["review_status"],"pending");let current:Value=sqlx::query_scalar("SELECT to_jsonb(p) FROM application_packets p WHERE id=$1").bind(packet_id).fetch_one(&mut c).await.unwrap();assert_eq!(current["revision"],2);assert!(current["approved_revision"].is_null());assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["state"],"PREPARING");assert_eq!(packet_archive_value(&mut c,packet_id,1).await["fields"],packet["fields"]);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_answer_advances_only_current_packet_siblings_and_keeps_others_unchanged(){
    let(mut c,packet,intent)=owner_question_packet().await;let first=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let second=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][8]),Value::Null).await.unwrap();let other_id=Uuid::new_v4();let other=json!({"id":other_id,"packet_id":Uuid::new_v4(),"packet_revision":1,"state":"pending","private":"retained"});browser_save(&mut c,&format!("exec_q:{other_id}"),other.clone()).await;let stale_id=Uuid::new_v4();let stale=json!({"id":stale_id,"packet_id":packet["id"],"packet_revision":99,"state":"pending"});browser_save(&mut c,&format!("exec_q:{stale_id}"),stale.clone()).await;
    owner_question_call(&mut c,&owner_question_answer_path(&first),json!({"expected_revision":1,"answer":"Day"})).await.unwrap();let updated=browser_pref(&mut c,&format!("exec_q:{}",second["id"].as_str().unwrap())).await;assert_eq!(updated["packet_revision"],2);assert_eq!(browser_pref(&mut c,&format!("exec_q:{other_id}")).await,other);assert_eq!(browser_pref(&mut c,&format!("exec_q:{stale_id}")).await,stale);assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["state"],"NEEDS_INPUT");let before=browser_snapshot(&mut c).await;assert_eq!(owner_question_call(&mut c,&owner_question_answer_path(&second),json!({"expected_revision":1,"answer":"Email"})).await.unwrap_err(),Failure("question_revision_conflict"));assert_eq!(browser_snapshot(&mut c).await,before);owner_question_call(&mut c,&owner_question_answer_path(&updated),json!({"expected_revision":2,"answer":"Email"})).await.unwrap();assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["state"],"PREPARING");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_answer_rejects_paused_expired_invalid_choice_and_changed_context(){
    let(mut c,packet,intent)=owner_question_packet().await;let question=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let qkey=format!("exec_q:{}",question["id"].as_str().unwrap());let ikey=format!("exec:{}",intent["id"].as_str().unwrap());let path=owner_question_answer_path(&question);
    for index in 0..4{browser_save(&mut c,&qkey,question.clone()).await;browser_save(&mut c,&ikey,intent.clone()).await;let(mut q,mut i)=(question.clone(),intent.clone());let text=if index==2{"Unsupported"}else{"Day"};let expected=match index{0=>{i["state"]=json!("PAUSED");"question_expired_or_application_cancelled"},1=>{q["expires_at"]=json!("2000-01-01T00:00:00Z");"question_expired_or_application_cancelled"},2=>"answer_must_match_option",_=>{q["context_digest"]=json!("changed");"packet_context_stale"}};browser_save(&mut c,&qkey,q).await;browser_save(&mut c,&ikey,i).await;let before=browser_snapshot(&mut c).await;assert_eq!(owner_question_call(&mut c,&path,json!({"expected_revision":1,"answer":text})).await.unwrap_err(),Failure(expected));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i32>("SELECT revision FROM application_packets WHERE id=$1").bind(packet["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap(),1);}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_question_dropped_ack_rolls_back_packet_archive_answer_and_intent(){
    let(mut c,packet,intent)=owner_question_packet().await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_dashboard_question_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_q:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_dashboard_question_drop BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_dashboard_question_drop()").execute(&mut c).await.unwrap();assert_eq!(owner_question_call(&mut c,&owner_question_answer_path(&q),json!({"expected_revision":1,"answer":"Day"})).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);let field:Value=sqlx::query_scalar("SELECT to_jsonb(f) FROM application_packet_fields f WHERE id=$1").bind(packet["fields"][7]["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert!(field["human_answer"].is_null());assert_eq!(field["answer_revision"],packet["fields"][7]["answer_revision"]);sqlx::raw_sql("DROP TRIGGER fixture_dashboard_question_drop ON owner_preferences;DROP FUNCTION fixture_dashboard_question_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_reuse_is_separate_and_changed_answer_cannot_keep_old_approval(){
    let(mut c,packet,intent)=owner_question_packet().await;let field=&packet["fields"][7];let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,field),Value::Null).await.unwrap();let reuse=format!("/api/v1/execution/questions/{}/approve-reuse",q["id"].as_str().unwrap());assert_eq!(owner_question_call(&mut c,&reuse,Value::Null).await.unwrap_err(),Failure("current_answer_required"));owner_question_call(&mut c,&owner_question_answer_path(&q),json!({"expected_revision":1,"answer":"Day"})).await.unwrap();let approved=owner_question_call(&mut c,&reuse,Value::Null).await.unwrap();assert_eq!(approved["reuse_approved"],true);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'aa_ans:')").fetch_one(&mut c).await.unwrap(),0);
    let packet_id=packet["id"].as_str().unwrap().parse().unwrap();packet_edit(&mut c,packet_id,&format!("/questions/{}",field["id"].as_str().unwrap()),json!({"expected_revision":2,"answer":"Night"})).await.unwrap();let before=browser_snapshot(&mut c).await;assert_eq!(owner_question_call(&mut c,&reuse,Value::Null).await.unwrap_err(),Failure("answer_changed_review_again"));assert_eq!(browser_snapshot(&mut c).await,before);
}
