#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_reuse_copies_only_compatible_current_context_and_never_browser_authority(){
    let(mut c,packet,intent)=owner_question_packet().await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();owner_question_call(&mut c,&owner_question_answer_path(&q),json!({"expected_revision":1,"answer":"Day"})).await.unwrap();owner_question_call(&mut c,&format!("/api/v1/execution/questions/{}/approve-reuse",q["id"].as_str().unwrap()),Value::Null).await.unwrap();let job=Uuid::new_v4();sqlx::query("INSERT INTO jobs SELECT (jsonb_populate_record(NULL::jobs,to_jsonb(j)||jsonb_build_object('id',$2::uuid,'job_url','https://www.naukri.com/job-listings-fictional-123456789013'))).* FROM jobs j WHERE j.id=$1").bind(packet["job_id"].as_str().unwrap().parse::<Uuid>().unwrap()).bind(job).execute(&mut c).await.unwrap();let target=packet_create(&mut c,job,"fictional-target-question-reuse",json!([{"question":"Preferred shift?","options":["Day","Night"],"field_type":"multiple_choice","required":true}])).await.unwrap();let mut target_intent=intent.clone();let target_id=Uuid::new_v4();target_intent["id"]=json!(target_id);target_intent["job_id"]=json!(job);target_intent["packet_id"]=target["id"].clone();browser_save(&mut c,&format!("exec:{target_id}"),target_intent.clone()).await;let field=&target["fields"][7];let path=format!("/api/v1/execution/{target_id}/questions/{}/reuse/{}",field["id"].as_str().unwrap(),q["id"].as_str().unwrap());let copied=owner_question_call(&mut c,&path,Value::Null).await.unwrap();assert_eq!(copied["revision"],2);assert_eq!(copied["fields"][7]["effective_answer"],"Day");assert_eq!(copied["fields"][7]["answer_revision"],field["answer_revision"].as_i64().unwrap()+1);assert_eq!(copied["fields"][7]["review_status"],"pending");assert!(copied["approved_revision"].is_null());assert_eq!(browser_pref(&mut c,&format!("exec:{target_id}")).await,target_intent);
    sqlx::query("UPDATE jobs SET description='Changed fictional listing' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();let before=browser_snapshot(&mut c).await;assert!(owner_question_call(&mut c,&path,Value::Null).await.is_err());assert_eq!(browser_snapshot(&mut c).await,before);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_form_reply_revokes_old_plan_and_tracks_actual_field_revision(){
    let(mut c,context,packet)=browser_command_fixture().await;let task=browser_task_open(&mut c,&context,&packet).await;let task=browser_task_event(&mut c,&context,&task,"bind",json!({"tab_id":50})).await["data"]["task"].clone();let mut observation=browser_form_observation(&packet);observation["fields"]=json!([{"field_id":"f1","kind":"date","label":"Start date","section":"Employment entry one","semantic_key":"a".repeat(64),"required":true}]);let data=browser_form_inspect(&mut c,&context,&packet,json!({"task_id":task["id"],"expected_task_version":task["version"],"inspection":observation})).await;let task=&data["task"];let asked=browser_form_native(&mut c,"ask_form_questions",&context,json!({"task_id":task["id"],"expected_task_version":task["version"]})).await.unwrap();let q=&asked["data"]["questions"][0];let answered=owner_question_call(&mut c,&owner_question_answer_path(q),json!({"expected_revision":q["packet_revision"],"answer":"2020-01-01"})).await.unwrap();let saved=browser_pref(&mut c,&format!("ext_task:{}",task["id"].as_str().unwrap())).await;assert_eq!(saved["state"],"PACKET_READY");assert!(saved["plan_id"].is_null());assert!(saved["authorization_id"].is_null());assert_eq!(saved["field_answer_revisions"][q["field_id"].as_str().unwrap()],answered["answer_revision"]);assert_eq!(saved["counts"]["missing"],0);assert_eq!(saved["reason"],"owner_answer_saved_fresh_inspection_required");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_questions_http_auth_strict_revision_and_scope_listing(){
    let(mut c,packet,intent)=owner_question_packet().await;let(url,stop,server)=http_fixture_values(queue_runtime_values()).await;let http=client();let ask=format!("{url}{}",owner_question_ask_path(&intent,&packet["fields"][7]));assert_eq!(http.post(&ask).send().await.unwrap().status(),401);assert_eq!(http.post(&ask).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).send().await.unwrap().status(),403);let response=http.post(&ask).bearer_auth(HOST_TOKEN).send().await.unwrap();assert_eq!(response.status(),200);let q=response.json::<Value>().await.unwrap();let path=format!("{url}{}",owner_question_answer_path(&q));let before=browser_snapshot(&mut c).await;for revision in [json!(1.0),json!(true),json!("1")] {assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).json(&json!({"expected_revision":revision,"answer":"Day"})).send().await.unwrap().status(),422);}assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).json(&json!({"expected_revision":1,"answer":"Day"})).send().await.unwrap().status(),200);let listed=http.get(format!("{url}/api/v1/execution/questions")).bearer_auth(HOST_TOKEN).send().await.unwrap().json::<Value>().await.unwrap();assert_eq!(listed.as_array().unwrap().len(),1);assert_eq!(listed[0]["state"],"answered");assert_eq!(http.get(&path).bearer_auth(HOST_TOKEN).send().await.unwrap().status(),405);stop.cancel();server.await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_reasks_expired_ordinary_prompt_but_never_reenrolls_unknown_delivery(){
    let(mut c,packet,intent)=owner_question_packet().await;let path=owner_question_ask_path(&intent,&packet["fields"][7]);let question=owner_question_call(&mut c,&path,Value::Null).await.unwrap();let key=format!("exec_q:{}",question["id"].as_str().unwrap());let mut old=question.clone();old["state"]=json!("sent");old["expires_at"]=json!("2000-01-01T00:00:00Z");old["message_ids"]=json!([51,52]);old["expired_message_ids"]=json!([50]);browser_save(&mut c,&key,old.clone()).await;let renewed=owner_question_call(&mut c,&path,Value::Null).await.unwrap();assert_eq!(renewed["id"],question["id"]);assert_eq!(renewed["state"],"pending");assert_eq!(renewed["message_ids"],json!([]));assert_eq!(renewed["expired_message_ids"],json!([50,51,52]));assert_ne!(renewed["expires_at"],old["expires_at"]);old["state"]=json!("delivery_unknown");old["delivery_lease"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&key,old.clone()).await;assert_eq!(owner_question_call(&mut c,&path,Value::Null).await.unwrap(),old);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_dashboard_concurrent_answers_have_one_winner_and_one_immutable_archive(){
    let(mut c,packet,intent)=owner_question_packet().await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let path=owner_question_answer_path(&q);let mut other=connection().await;let(one,two)=tokio::join!(owner_question_call(&mut c,&path,json!({"expected_revision":1,"answer":"Day"})),owner_question_call(&mut other,&path,json!({"expected_revision":1,"answer":"Night"})));assert_eq!(usize::from(one.is_ok())+usize::from(two.is_ok()),1);assert!(matches!(one.err().or(two.err()).unwrap().0,"question_already_answered"|"execution_database_error"));let revision:i32=sqlx::query_scalar("SELECT revision FROM application_packets WHERE id=$1").bind(packet["id"].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert_eq!(revision,2);let archived=packet_archive_value(&mut c,packet["id"].as_str().unwrap().parse().unwrap(),1).await;assert_eq!(archived["fields"],packet["fields"]);
}
